'use strict';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cash=v=>v===null||v===undefined?'—':Number(v).toLocaleString('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:Math.abs(Number(v))<.01?6:2});
const pct=v=>v===null||v===undefined?'—':(v*100).toFixed(1)+'%';
const date=v=>v?new Date(v*1000).toLocaleString('en-US',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'—';
const dateTime=v=>v?new Date(v*1000).toLocaleString('en-US',{year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'—';
const human=v=>String(v??'').replaceAll('_',' ');
const uuid=()=>crypto.randomUUID();
const apiBase=location.pathname.startsWith('/hosted-pilot/')?'/hosted-pilot/v1/':location.pathname.startsWith('/app/')?'/app/v1/':'/v1/';
let credential='',busy=false,refreshPending=false,timer,route='overview',selected='',snapshot,detail,report,invoiceRows=[],invoiceReady=false;
let pairMode=false;
const pairStorageKey='reins-paired-session:'+location.origin;
let group='customer',approvalTab='operations',page=1,days=30,filters={},sort='created';
const drafts=new Map();
const selectedReviews=new Set();
let invoicePreview='',dialogOrigin=null,connectionError=false;
function parseObject(value,label){let result;try{result=JSON.parse(value);}catch{throw Error(label+': enter valid JSON (double-quoted field names and no trailing commas).');}if(!result||Array.isArray(result)||typeof result!=='object')throw Error(label+': enter an object with named fields.');return result;}

const pages={overview:['Overview','Your agent operations, at a glance.'],runs:['Runs','Find expensive work. Understand every step.'],attribution:['Attribution','Understand the cost of each customer and workflow.'],exceptions:['Exceptions','Prioritize the issues that need a decision.'],budgets:['Budgets','Protect the work that matters. Keep spending within reach.'],policies:['Policies','Set the rules for the next task.'],experiments:['Experiments','Compare quality first. Then the cost of an accepted result.'],approvals:['Approvals','Review actions, confirm results and follow handoffs.'],settings:['Settings','Manage your private workspace and reconcile its costs.']};
const groups=[['Observe',[['overview','◫'],['runs','≋']]],['Understand',[['attribution','▥'],['exceptions','!']]],['Control',[['budgets','◷'],['policies','⌘'],['experiments','⇄']]],['Operate',[['approvals','✓'],['settings','⚙']]]];
function button(text,act,id='',cls=''){return `<button type="button" class="${esc(cls)}" data-act="${esc(act)}" data-id="${esc(id)}">${esc(text)}</button>`;}
function chip(text,kind=''){return `<span class="chip ${esc(kind)}">${esc(text)}</span>`;}
function status(value){return chip(human(value),['paused','needs_inspection','uncertain_charge','pending','awaiting_settlement'].includes(value)?'warning':['rejected','reject','failed','cancelled'].includes(value)?'danger':['queued','ready'].includes(value)?'neutral':'');}
function panel(title,body,sub='',actions=''){return `<section class="panel"><div class="panel-head"><div><h2>${esc(title)}</h2>${sub?`<p>${esc(sub)}</p>`:''}</div>${actions}</div><div class="panel-body">${body}</div></section>`;}
function metric(label,value,sub='',highlight=false){return `<div class="metric ${highlight?'highlight':''}"><span class="label">${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(sub)}</small></div>`;}
function empty(title,sub=''){return `<div class="empty"><strong>${esc(title)}</strong>${esc(sub)}</div>`;}
function table(headers,rows){return `<div class="scroll"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function progress(used,cap){const r=Number(cap)>0?Number(used)/Number(cap):0;return `<div class="progress-track" role="meter" aria-label="Budget occupied" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(r*100)}"><span class="progress-fill ${r>=1?'danger':r>=.8?'warning':''}" data-width="${Math.min(100,r*100)}"></span></div>`;}
function bars(rows){if(!rows.length)return empty('No recorded costs yet');const max=Math.max(...rows.map(r=>Number(r.cost)),.000001);return rows.slice(0,8).map(r=>`<div class="bar-row"><span class="name" title="${esc(r.name||r.id)}">${esc(r.name||r.id)}</span><div class="bar-track"><span class="bar-fill" data-width="${Number(r.cost)/max*100}"></span></div><strong>${cash(r.cost)}</strong></div>`).join('');}
function budgetUsageChart(){
 const rows=snapshot.q.workflows.filter(w=>Number(w.budget)>0).map(w=>({
  ...w,spent:Math.max(0,Number(w.cost)||0),held:Math.max(0,Number(w.reserved)||0),cap:Number(w.budget)
 })).sort((a,b)=>(b.spent+b.held)/b.cap-(a.spent+a.held)/a.cap).slice(0,8);
 if(!rows.length)return empty('No task budgets in this selection','Run a task with a budget to see its spending here.');
 return `<div class="chart-key"><span><i class="key-spent"></i>Recorded API spend</span><span><i class="key-held"></i>Unresolved reservation</span><span><i></i>Remaining limit</span></div><div class="usage-chart">${rows.map(w=>{
  const company=snapshot.company?.tasks?.find(t=>t.id===w.id)?.input?.company;
  const title=company?company+' · '+w.id.slice(-8):w.id;
  const spentPct=Math.min(100,w.spent/w.cap*100),heldPct=Math.min(100-spentPct,w.held/w.cap*100);
  const occupied=(w.spent+w.held)/w.cap*100;
  return `<div class="usage-row"><div class="usage-label">${button(title,'run',w.id,'link-button')}<strong>${occupied.toFixed(1)}%</strong></div><div class="usage-track" role="meter" aria-label="${esc(title)} budget occupied" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,occupied).toFixed(1)}"><span class="usage-spent" data-width="${spentPct}"></span><span class="usage-held" data-width="${heldPct}"></span></div><small>${cash(w.spent)} spent${w.held?` · ${cash(w.held)} reserved`:''} / ${cash(w.cap)} limit</small></div>`;
 }).join('')}</div><p class="section-note">Each bar compares one task with its own limit. Only tasks shown in the current ${days===3650?'all-history':days+'-day'} selection are included; limits are not billed costs.</p>`;
}
function issueMixChart(){
 const counts=new Map();for(const issue of snapshot.pilot.issues.filter(i=>i.state==='open'))counts.set(issue.kind,(counts.get(issue.kind)||0)+1);
 if(!counts.size)return empty('No open issue records','Issue categories appear after a task needs review.');
 const labels={shared_budget:'Shared budget stop',uncertain:'Uncertain charge'};
 const total=[...counts.values()].reduce((a,b)=>a+b,0);
 return `<div class="issue-chart">${[...counts].sort((a,b)=>b[1]-a[1]).map(([kind,count])=>`<div class="issue-row"><div><span>${esc(labels[kind]||human(kind))}</span><strong>${count} of ${total}</strong></div><div class="issue-track" role="meter" aria-label="${esc(labels[kind]||human(kind))} issue records" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${count}"><span data-width="${count/total*100}"></span></div></div>`).join('')}</div><p class="section-note">Open issue records by type. Counts describe this workspace, not an error rate.</p>`;
}
function trend(rows){if(!rows.length)return empty('Your spending history starts here','Charts appear as your agents record work.');const w=650,h=180,max=Math.max(...rows.map(r=>Number(r.cost)),.000001);const points=rows.map((r,i)=>[35+i*(w-65)/Math.max(rows.length-1,1),h-25-Number(r.cost)/max*(h-45)]);const path=points.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ');return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Recorded task cost by start date"><title>Task cohort costs by day</title>${[0,1,2].map(i=>`<line class="gridline" x1="35" y1="${20+i*67}" x2="630" y2="${20+i*67}"/>`).join('')}<path d="${path} L${points.at(-1)[0]},155 L35,155 Z" fill="#edf4e5"/><path d="${path}" fill="none" stroke="#6d9b48" stroke-width="2.5"/>${points.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="3.5" fill="#739e50"><title>${esc(rows[i].day)}: ${cash(rows[i].cost)}</title></circle>`).join('')}<text x="35" y="177">${esc(rows[0].day)}</text><text x="630" y="177" text-anchor="end">${esc(rows.at(-1).day)}</text><text x="35" y="13">${cash(max)}</text></svg>`;}
function jsonBox(value){return `<pre>${esc(JSON.stringify(value,null,2))}</pre>`;}
function field(name,label,value='',type='text',extra=''){return `<label class="field">${esc(label)}<input name="${esc(name)}" type="${esc(type)}" value="${esc(value)}" ${extra}></label>`;}
function select(name,label,options,value=''){return `<label class="field">${esc(label)}<select name="${esc(name)}">${options.map(o=>{const a=Array.isArray(o)?o:[o,human(o)];return `<option value="${esc(a[0])}" ${a[0]===value?'selected':''}>${esc(a[1])}</option>`;}).join('')}</select></label>`;}
function area(name,label,value={},rows=4){return `<label class="field wide">${esc(label)}<textarea name="${esc(name)}" rows="${rows}">${esc(typeof value==='string'?value:JSON.stringify(value,null,2))}</textarea></label>`;}
function form(id,fields,submit='Save'){return `<form id="${esc(id)}" class="form-grid">${fields}<div class="form-footer"><button class="primary">${esc(submit)}</button></div></form>`;}
function notify(text,error=false){if(error){$('#notice').textContent=text;$('#notice').hidden=false;}else{$('#toast').textContent=text;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,3500);}}
async function api(path,body={},timeoutMs=15000){let r;try{r=await fetch(apiBase+path,{signal:AbortSignal.timeout(timeoutMs),method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+credential},body:JSON.stringify(body)});}catch{throw Error('Connection interrupted. Check the service, then refresh before retrying a change.');}const data=await r.json();if(!r.ok){if(pairMode&&(r.status===401||r.status===403)){localStorage.removeItem(pairStorageKey);credential='';showPair('This browser pairing expired. Enter a new token.');}throw Error(r.status===401||r.status===403?'Workspace access expired. Pair this browser again.':data.error||'Request could not be completed');}return data;}
function navigate(name,id=''){location.hash=name+(id?'?id='+encodeURIComponent(id):'');if(route===name&&selected===id)refresh(true);}
function readRoute(){const [p,q]=location.hash.slice(1).split('?');route=pages[p]?p:'overview';selected=new URLSearchParams(q||'').get('id')||'';$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');drawNav();refresh(true);}
function drawNav(){const count=snapshot? snapshot.ops.alerts.filter(a=>!a.acknowledged).length+snapshot.alerts.alerts.filter(a=>a.state==='open'&&a.ack!==a.version).length:0;$('#navigation').innerHTML=groups.map(([name,items])=>`<div class="nav-group">${name}</div>${items.map(([id,icon])=>`<a href="#${id}" class="nav-item ${route===id?'active':''}" ${route===id?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${pages[id][0]}${id==='exceptions'&&count?`<span class="nav-badge">${count}</span>`:''}</a>`).join('')}`).join('');$('#breadcrumb').textContent='Workspace / '+pages[route][0];$('#page-title').textContent=pages[route][0];$('#page-description').textContent=pages[route][1];}
function drawFilters(){const common=['overview','runs','attribution'].includes(route)&&!selected;$('#filters').hidden=!credential||!common;if(!common)return;const opt=(name,label)=>`<select data-filter="${name}" aria-label="${label}"><option value="">All ${label.toLowerCase()}</option>${(snapshot?.q.options[name]||[]).map(v=>`<option ${filters[name]===v?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('')}</select>`;$('#filters').innerHTML=`<select id="date-range" aria-label="Time range">${[7,30,90,3650].map(n=>`<option value="${n}" ${days===n?'selected':''}>${n===3650?'All history':'Last '+n+' days'}</option>`).join('')}</select>${opt('customer','Customers')}${opt('team','Teams')}${opt('task_type','Workflows')}<small>Tasks started in this period · UTC</small>`;}
async function refresh(force=false){if(!credential){drawNav();return;}if(force){$('#content').inert=true;$('#content').classList.add('refreshing');}if(busy){refreshPending=refreshPending||force;return;}busy=true;$('#content').setAttribute('aria-busy','true');$('#sync-status').textContent='Updating workspace…';const target=route,id=selected;try{const query={...filters,start:Date.now()/1000-days*86400,end:Date.now()/1000+1,page,page_size:25,group_by:group,sort};const [q,pilot,ops,budgets,alerts,approvals,catalog,pools,company,pairs]=await Promise.all([api('console/query',query),api('pilot/status'),api('ops/status'),api('console/budgets/list'),api('console/alerts/list'),api('console/approvals/list'),api('console/experiments/catalog'),api('console/pools'),api('console/company/list'),api('worker-pair/list')]);snapshot={q,pilot,ops,budgets,alerts,approvals,catalog,pools,company,pairs};if(connectionError){$('#notice').hidden=true;connectionError=false;}$('#workspace-label').textContent=pools.workspace_label;if(target==='runs'&&id)detail=await api('console/detail',{workflow_id:id});if(target==='experiments'&&id)report=await api('console/experiments/report',{id});if(route!==target||selected!==id)return;if(!selected&&page>1&&page>Math.ceil(q.total/25)){page=Math.max(1,Math.ceil(q.total/25));refreshPending=true;return;}$('#connection-state').textContent=pools.workspace_label.startsWith('Synthetic pilot')?'Connected to hosted pilot':'Connected to local service';$('#sync-status').textContent='Connected · updates every 5s';$('#last-updated').textContent='Updated '+new Date().toLocaleTimeString();$('#mode-label').textContent=[...new Set(q.workflows.map(w=>w.mode))].map(m=>m==='enforce'?'Control':'Observe').join(' + ')||'Connected';drawNav();if(force||(!(route==='settings'&&invoiceReady)&&!$('#dialog').open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))){drawFilters();draw();}}catch(e){connectionError=true;notify(e.message,true);$('#sync-status').textContent='Connection needs attention';}finally{busy=false;$('#content').setAttribute('aria-busy','false');if(!refreshPending){$('#content').inert=false;$('#content').classList.remove('refreshing');}if(refreshPending){refreshPending=false;queueMicrotask(()=>refresh(true));}}}
function draw(){if(!snapshot)return;$('#page-actions').innerHTML=route==='runs'&&!selected?button('New task','new-task','','primary'):route==='budgets'?button('New period budget','new-budget','','primary'):route==='policies'?button('New policy','new-policy','','primary'):route==='experiments'&&!selected?button('Create experiment','new-experiment','','primary'):'';const fn={overview:overview,runs:runs,attribution:attribution,exceptions:exceptions,budgets:budgets,policies:policies,experiments:experiments,approvals:approvals,settings:settings}[route];$('#content').innerHTML=fn();restoreDrafts();}
function overview(){const {q,ops,alerts}=snapshot,s=q.summary;const open=ops.alerts.length+alerts.alerts.filter(a=>a.state==='open').length;return `<div class="metrics">${metric('Recorded cost',cash(s.cost),q.total+' tasks in this period',true)}${metric('Cost / accepted result',cash(s.cost_per_accepted),s.accepted+' accepted results')}${metric('Acceptance rate',pct(s.acceptance_rate),s.evaluated+' evaluated tasks')}${metric('Needs attention',String(open),snapshot.pilot.reviews.filter(r=>r.state==='pending').length+' results awaiting review')}</div><div class="grid">${panel('Spending over time',trend(q.trend),'Lifetime recorded cost, grouped by task start date')}${panel('Task cost distribution',bars(q.distribution),'Most expensive tasks in this selection')}</div><div class="grid">${panel('Cost by '+human(group),bars(q.groups),'View the customers and workflows behind your spend',button('View attribution','nav','attribution'))}${panel('Your next decisions',attentionList(4),'Recent issues and budget alerts',button('View all','nav','exceptions'))}</div>${panel('Shared and period budgets',budgetCards(), 'Used funds and unresolved reservations shown separately')}`;}
function budgetCards(){const b=snapshot.budgets.budgets.filter(x=>x.active);const pools=snapshot.pools.pools;return b.length||pools.length?`<div class="budget-chain">${b.slice(0,4).map(x=>`<div class="budget-node"><small>${esc(x.id)} · ${esc(x.scope)}</small><strong>${cash(x.spent)} <span class="muted small">/ ${cash(x.amount)}</span></strong>${progress(Number(x.spent)+Number(x.reserved),x.amount)}<small>${cash(x.reserved)} reserved</small>${x.forecast?`<small>Projected ${cash(x.forecast)}</small>`:''}</div>`).join('')}${pools.slice(0,3).map(p=>`<div class="budget-node"><small>${esc(p.team_id)} · shared pool</small><strong>${cash(p.committed)} <span class="muted small">/ ${cash(p.budget)}</span></strong>${progress(p.committed,p.budget)}<small>${cash(p.critical_reserve)} protected for critical work</small></div>`).join('')}</div>`:empty('Set your first shared budget','Create a period budget or a shared pool to protect spending across tasks.');}
function attentionList(limit=100){const items=[];for(const a of snapshot.alerts.alerts.filter(a=>a.state==='open'))items.push(`<div class="attention-row"><span class="attention-icon">!</span><div><strong>${esc(a.body.title)}</strong><p>${cash(a.body.spent)} spent · ${cash(a.body.reserved)} reserved</p><div class="actions">${button('View budget','nav','budgets')}${a.ack!==a.version?button('Acknowledge','budget-ack',a.id):chip('Acknowledged')}</div></div></div>`);for(const a of snapshot.ops.alerts){items.push(`<div class="attention-row"><span class="attention-icon">!</span><div><strong>${esc(human(a.kind))}</strong><p>${esc(a.task_id)} · ${date(a.updated)}</p><div class="actions">${button('Inspect task','run',a.workflow_id)}${button('Take action','issue',a.issue_id)}${a.acknowledged?chip('Acknowledged'):button('Acknowledge','issue-ack',a.issue_id)}</div></div></div>`);}return items.slice(0,limit).join('')||empty('Nothing needs attention','New issues will appear here as your agents work.');}
function runs(){if(selected&&detail)return runtimePlan(detail)+runDetail();const q=snapshot.q;return `<div class="actions tabs">${button('Highest cost','sort','cost',sort==='cost'?'selected':'')}${button('Slowest completed','sort','duration',sort==='duration'?'selected':'')}${button('Newest','sort','created',sort==='created'?'selected':'')}${button('Export CSV','runs-csv')}<input id="run-search" placeholder="Search task or workflow" aria-label="Search runs" value="${esc(filters.search||'')}"><select id="run-state" aria-label="Run status"><option value="">All statuses</option>${q.options.state.map(s=>`<option value="${esc(s)}" ${filters.state===s?'selected':''}>${esc(human(s))}</option>`).join('')}</select></div>${panel('All task runs',q.workflows.length?table(['Task','Started (your time)','Status','Duration','Recorded cost','Budget occupied','Result'],q.workflows.map(w=>[button(w.id,'run',w.id,'link-button')+`<small>${esc(w.task_type)} · ${esc(w.customer)}</small>`,esc(dateTime(w.created)),status(w.state),w.duration===null?'—':(w.duration.toFixed(1)+'s'),`<strong>${cash(w.cost)}</strong><small>${w.calls} operations · ${w.failed_calls} failed</small>`,`${cash(Number(w.admission_cost)+Number(w.reserved))} / ${cash(w.budget)}${progress(Number(w.admission_cost)+Number(w.reserved),w.budget)}`,w.accepted===null?chip('Not evaluated','neutral'):chip(w.accepted?'Accepted':'Not accepted',w.accepted?'':'warning')])):empty('No matching tasks','Change your filters or connect an Agent.'),q.total+' tasks',button('Clear filters','clear-filters'))}<div class="pagination"><span>Page ${page} of ${Math.max(1,Math.ceil(q.total/25))}</span><div class="actions">${page>1?button('Previous','page',String(page-1)):''}${page*25<q.total?button('Next','page',String(page+1)):''}</div></div>${queuedRuns()}`;}
function queuedRuns(){const rows=snapshot.catalog.runs||[];if(!rows.length)return '';return panel('Managed deployment runs',table(['Task','Deployment','Configuration','Started (your time)','Status',''],rows.map(r=>[esc(r.spec.run_id),esc(r.spec.deployment),'v'+r.spec.deployment_version,esc(dateTime(r.created)),status(r.state),['queued','provisioning'].includes(r.state)?'Waiting for worker':button('Inspect','run',r.spec.run_id)])));}
function runtimePlan(d){const p=d.runtime_assignment;if(!p)return '';const cfg=p.configuration||{},e=p.quality_evidence||{},model=cfg.config?.model||'Specified by the Agent adapter';return panel('Hosted execution plan',`<div class="metrics">${metric('Deployment',p.deployment,'Version '+p.version)}${metric('Selected variant',cfg.variant||'—')}${metric('Model',model)}${metric('Runtime control',p.stopped?'Stopped further calls':p.escalated?'Escalated to baseline':'Active')}</div><div class="metrics">${metric('Accepted in reviewed set',e.accepted===undefined?'—':e.accepted+' / '+e.cases)}${metric('Cost / accepted',cash(e.selected_cost_per_accepted))}${metric('Compared with baseline',e.savings_fraction===null?'—':pct(e.savings_fraction)+' lower cost')}</div><p class="section-note">Results describe the frozen comparison, not customer production savings. The connected Agent requests a runtime decision before paid work; Reins checks its model and budget again at reservation.</p>`);}
function runDetail(){const d=detail;const calls=d.requests;return `<div class="actions tabs">${button('← All runs','nav','runs')}${button('Copy for agent','copy-trace')}${d.state==='running'?button('Pause','workflow-action','pause'):d.state==='paused'?button('Resume','workflow-action','resume'):''}${!['completed','wrapping'].includes(d.state)?button('Start wrap-up','workflow-action','wrapup'):''}${button('Create review case','capture-run')}</div><div class="metrics">${metric('Recorded calls',cash(d.known_cost),cash(d.reserved_cost)+' reserved',true)}${metric('Budget',cash(d.budget),cash(d.budget_state.work_remaining)+' available for work')}${metric('Operations',String(calls.length),calls.filter(c=>c.success===0).length+' failed operations')}${metric('Task state',human(d.state),d.customer_id+' / '+d.team_id)}</div><div class="split-detail">${panel(d.workflow_id,`<div class="info-list"><div><dt>Workflow</dt><dd>${esc(d.task_type)}</dd></div><div><dt>Policy</dt><dd>${esc(d.policy_version)}</dd></div></div><h3 class="section-heading">Execution steps</h3>${calls.length?table(['Step / task','Type','Recorded interval','Tokens','Cost'],calls.map(c=>[button(c.tool||c.model,'step',c.request_id,'link-button')+`<small>${esc(c.task_id)}</small>`,chip(c.category),`${date(c.created)}<small>${c.settled?(c.settled-c.created).toFixed(2)+'s to settlement':'Awaiting settlement'}</small>`,esc((c.usage.input_tokens||0)+(c.usage.output_tokens||0)),`<strong>${cash(c.cost)}</strong>${c.cost===null?`<small>${cash(c.reserved)} reserved</small>`:''}${c.success===0?'<small>Failed; cost retained</small>':''}`])):empty('No operations recorded')}<details><summary>Budget constraint chain and task tree</summary>${table(['Task','Parent','Task cap','Activity'],d.tasks.map(t=>[esc(t.task_id),esc(t.parent_task_id||'Root'),cash(t.budget),status(d.activity.tasks.find(n=>n.task_id===t.task_id)?.state||'ready')]))}<p class="section-note">Task, ancestor and shared limits all apply. Reservations remain held until settlement.</p>${d.period_budgets.map(b=>`<div class="budget-node"><small>${esc(b.id)} · ${esc(b.scope)}</small>${cash(b.spent)} + ${cash(b.reserved)} reserved / ${cash(b.amount)}</div>`).join('')}</details>`) }${panel('Execution timeline',`<ol class="timeline">${d.events.slice(-100).reverse().map(e=>`<li><time>${date(e.created)}</time>${esc(human(e.payload.reason||e.kind))}<small class="muted"> · ${esc(e.task)}</small></li>`).join('')}</ol>${d.events.length>100?`<p class="section-note">Showing latest 100 of ${d.events.length} events. Full history is included in the copied trace.</p>`:''}`)}</div>${panel('Results and handoffs',`<div class="metrics">${metric('Recorded total cost',cash(d.economics.recorded_total_cost))}${metric('Revenue',cash(d.economics.revenue))}${metric('Margin',cash(d.economics.margin),d.economics.coverage_complete?'External costs recorded':'Record external costs to calculate margin')}${metric('Remaining cost P90',cash(d.forecast.remaining_p90),d.forecast.samples+' comparable historical tasks')}</div>${table(['Sender → Receiver','Goal','State','Receipt'],d.activity.handoffs.map(h=>[esc(h.sender+' → '+h.receiver),esc(h.goal),status(h.state_status),h.received_at?'Received':'Awaiting receipt']))}`)}`;}
function attribution(){const q=snapshot.q;return `<div class="tabs">${['customer','team','task_type','task','model','tool'].map(g=>button(human(g),'group',g,group===g?'selected':'')).join('')}${button('Export CSV','attribution-csv')}</div><div class="metrics">${metric('Recorded cost',cash(q.summary.cost),'Includes failed and retried work',true)}${metric('Accepted results',String(q.summary.accepted))}${metric('Cost / accepted',cash(q.summary.cost_per_accepted))}${metric('Change vs previous period',cash(q.change.delta),'Equal-length task cohorts')}</div>${panel('Cost breakdown',table(['Name','Share','Cost','Tasks','Cost / accepted','Revenue','Margin'],q.groups.map(g=>[`<strong>${esc(g.name)}</strong>`,`${pct(g.share)}${progress(g.share,1)}`,cash(g.cost),esc(g.tasks),cash(g.cost_per_accepted),cash(g.revenue),cash(g.margin)])),'Grouped by '+human(group))}<div class="grid">${panel('Cost composition',bars(q.composition))}${panel('What changed',q.change.volume!==null?bars([{name:'Task volume',cost:Math.abs(Number(q.change.volume))},{name:'Cost per task',cost:Math.abs(Number(q.change.unit_cost))}])+`<p class="section-note">Task volume: ${cash(q.change.volume)}. Cost per task: ${cash(q.change.unit_cost)}. These signed changes add up to ${cash(q.change.delta)}.</p>`:empty('A new comparison period','A previous cohort is needed to separate volume from unit cost.'))}</div>`;}
function exceptions(){return panel('Open issues by type',issueMixChart(),'A quick view of what currently needs attention')+`<div class="grid">${panel('Attention queue',attentionList(),'Acknowledging records receipt; it does not resume work.')}${panel('Decision history',snapshot.alerts.audit.length?table(['Action','Object','When'],snapshot.alerts.audit.slice(0,30).map(a=>[esc(human(a.kind)),esc(a.subject),date(a.created)])):empty('No decisions yet'))}</div>${panel('Recorded task issues',table(['Issue','Task','Occurrences','Status','Action'],snapshot.pilot.issues.map(i=>[esc(human(i.kind)),button(i.task,'run',i.workflow,'link-button'),esc(i.body.count),status(i.state),i.state==='open'?button('Review','issue',i.id):'—'])),'Repeated evidence is grouped under its existing issue.')}`;}
function budgets(){return panel('Task budget use',budgetUsageChart(),'Recorded spend and pending reservations against each task limit')+panel('Budget overview',budgetCards())+panel('Period budgets',snapshot.budgets.budgets.length?table(['Budget / scope','Period (UTC)','Spent','Reserved','Limit','Projection','Status'],snapshot.budgets.budgets.map(b=>[button(b.id,'budget-detail',b.id,'link-button')+`<small>${esc(b.scope)}: ${esc(b.value)}</small>`,`${new Date(b.start*1000).toISOString().slice(0,10)} → ${new Date(b.end*1000).toISOString().slice(0,10)}`,cash(b.spent),cash(b.reserved),cash(b.amount)+progress(Number(b.spent)+Number(b.reserved),b.amount),cash(b.forecast),chip(b.active?'Active':'Outside period',b.active?'':'neutral')])):empty('No period budgets','Create a budget for your workspace, customer, team, workflow or model.'),'Actual spend and reservations determine admission. Forecasts are advisory.')+panel('Shared work pools',snapshot.pools.pools.length?table(['Pool','Customer / team','Committed','Budget','Critical reserve'],snapshot.pools.pools.map(p=>[esc(p.pool_id),esc(p.customer_id+' / '+p.team_id),cash(p.committed),cash(p.budget),cash(p.critical_reserve)])):empty('No shared pools yet'),'Protect critical work across concurrent tasks.',button('Create pool','new-pool'));}
function policies(){return panel('Execution policies',snapshot.pilot.policies.length?table(['Version','Task budget','Repeat limit','Failure limit','No-progress action','Inspect'],snapshot.pilot.policies.map(p=>[esc(p.id),cash(p.body.workflow.budget),esc(p.body.workflow.repeat_limit??'Default'),esc(p.body.workflow.failure_limit??'Default'),esc(human(p.body.progress.action)),button('View / duplicate','policy',p.id)])):empty('Create your first policy','Set a task budget and decide how Reins responds to repeated or stalled work.'),'Running tasks keep the policy version they started with.')+panel('Registered tools',snapshot.ops.tools.length?table(['Tool','Access','Approval','Version',''],snapshot.ops.tools.map(t=>[esc(t.name),t.policy.read_only?'Read only':'Writes data',t.policy.approval_required||!t.policy.read_only?'Required':'No additional read approval',esc(t.digest.slice(0,10)),button('Edit','tool',t.name)])):empty('No tools registered'),'Keep read and write permissions explicit.',button('Register tool','tool'));}
function experiments(){if(selected&&report)return experimentDetail();return panel('Experiments',snapshot.catalog.experiments.length?table(['Experiment','Status','Created',''],snapshot.catalog.experiments.map(e=>[button(e.id,'experiment',e.id,'link-button'),status(e.state),date(e.created),button('View results','experiment',e.id)])):empty('Compare your first execution plan','Start with reviewed cases and a registered Agent worker.'),'All variants run the same frozen inputs. Labels stay with the evaluator.')+`<div class="grid">${panel('Reviewed test sets',snapshot.catalog.suites.length?table(['Version','Cases'],snapshot.catalog.suites.map(s=>[esc(s.id),esc(s.cases)])):empty('No reviewed test sets','Confirm expected results in Approvals to build one.'), '',button('Review results','review-tab'))}${panel('Agent adapters',snapshot.catalog.adapters.length?table(['Version','Protocol'],snapshot.catalog.adapters.map(a=>[esc(a.id)+`<small>${esc(a.description)}</small>`,esc(a.protocol)])):empty('Register an Agent','Use the built-in Gemini adapter or your own installed callable.'),'Workers run trusted adapters on your own machine.',button('Register adapter','adapter'))}</div>${panel('Adopted configurations',snapshot.catalog.deployments.length?table(['Name','Adapter','Variant','Version',''],snapshot.catalog.deployments.map(d=>[esc(d.id),esc(d.body.adapter),esc(d.body.variant),esc(d.version),button('New task','deployed-task',d.id)+' '+button('Hosted task','hosted-task',d.id)+' '+button('Roll back','rollback',d.id)])):empty('No configuration adopted','A complete, quality-qualified experiment can be adopted for new tasks.'))}`;}
function experimentDetail(){const r=report;return `<div class="actions tabs">${button('← Experiments','nav','experiments')}${button('Print / save PDF','print')}${button('Download data','experiment-json')}${!['completed','cancelled'].includes(r.state)?button('Cancel remaining work','cancel-experiment',r.id,'danger'):''}</div>${panel(r.id,`<div class="metrics">${metric('Status',human(r.state))}${metric('Completed jobs',String(r.jobs.filter(j=>j.state==='completed').length),r.jobs.length+' total jobs')}${metric('Recorded experiment cost',cash(r.variants.reduce((n,v)=>n+Number(v.cost),0)))}${metric('Evaluation calls',cash(r.variants.reduce((n,v)=>n+Number(v.evaluation_cost),0)))}</div>${r.recommended?`<p class="success-copy">${esc(r.recommended)} has the lowest cost among qualified variants.</p>`:''}${table(['Variant','Accepted','Cost / accepted','Total cost','p95','Comparison',''],r.variants.map(v=>[esc(v.id)+(v.id===r.spec.baseline?' '+chip('Baseline','neutral'):''),`${v.accepted} / ${v.total} · ${pct(v.rate)}`,cash(v.cost_per_accepted),cash(v.cost),v.p95_ms===null?'—':(v.p95_ms/1000).toFixed(2)+'s',v.eligible?chip(v.savings_fraction>0?pct(v.savings_fraction)+' lower cost':'Quality qualified'):chip('Review details','neutral'),v.eligible?button('Adopt for new tasks','adopt',v.id):'—']))}<div class="budget-preview"><strong>Recorded cost by variant</strong>${bars(r.variants.map(v=>({name:v.id,cost:v.cost})))}<p class="section-note">Includes failures, retries and recorded evaluator calls. Pending charges prevent a cost comparison.</p></div><details><summary>Quality requirements and case status</summary>${jsonBox(r.spec.constraints)}${table(['Case','Variant','Status'],r.jobs.map(j=>[esc(j.case_id),esc(j.arm),status(j.state)]))}</details>`,'Frozen test set: '+r.spec.suite_id)}`;}
function approvals(){let body='';if(approvalTab==='operations'){body=snapshot.approvals.approvals.length?snapshot.approvals.approvals.map(a=>panel(a.body.tool_name,`<div class="info-list"><div><dt>Task</dt><dd>${button(a.body.task_id,'run',a.body.workflow_id,'link-button')}</dd></div><div><dt>Maximum cost</dt><dd>${cash(a.body.max_cost)}</dd></div></div><p>${esc(a.body.purpose)}</p>${jsonBox(a.body.arguments)}<div class="actions">${status(a.execution_state||a.state)}${a.expires?`<small class="muted">Expires ${date(a.expires)}</small>`:''}${a.state==='pending'?button('Approve exact call','approve',a.id,'primary')+button('Reject','reject',a.id,'danger'):''}</div>`,'Bound to this task, exact arguments and tool permission version.')).join(''):empty('No approval requests','Connected workers submit requests before protected operations.');}else if(approvalTab==='quality'){body=qualityReviews();}else body=panel('Agent handoffs',table(['From → To','Goal','State version','Receipt'],snapshot.ops.handoffs.map(h=>[esc(h.sender+' → '+h.receiver),esc(h.goal),`${esc(h.state_name)} v${h.version} ${status(h.state_status)}`,h.received_at?date(h.received_at):'Awaiting receiver'])));return `<div class="tabs">${[['operations','Operation approvals'],['quality','Quality review'],['handoffs','Handoffs']].map(([id,label])=>button(label,'approval-tab',id,approvalTab===id?'selected':'')).join('')}${approvalTab==='operations'?button('Request an approval','request-approval'):''}</div>${body}`;}
function qualityReviews(){return panel('Quality review',snapshot.pilot.reviews.length?snapshot.pilot.reviews.map(r=>`<article class="review-card"><h3>${esc(r.id)}</h3>${status(r.state)} ${button('Inspect run','run',r.workflow,'link-button')}<div class="review-columns"><div><p class="small muted">Original input</p>${jsonBox(r.body.submitted.input)}</div><div><p class="small muted">Observed output</p>${jsonBox(r.body.submitted.output)}</div></div>${r.state==='pending'?form('review-'+r.id,area('expected','Confirmed expected fields',{})+field('rubric_version','Rubric version','v1')+field('reviewer','Reviewer','','text','required')+field('reason','Review note','', 'text','required')+select('decision','Decision',[['approve','Confirm expected result'],['reject','Exclude from test set']]),'Save review'):''}</article>`).join(''):empty('No results to review','Create a case from a run, or submit results through your Agent integration.'),'Confirmed expectations do not change the original task outcome.')+panel('Create a frozen test set',form('suite',field('suite_id','New test-set version','', 'text','required')+`<fieldset class="wide review-picker"><legend>Select approved reviews</legend><div class="actions">${button('Select all','select-reviews')}${button('Clear selection','clear-reviews')}</div>${snapshot.pilot.reviews.filter(r=>r.state==='approve').map(r=>`<label><input type="checkbox" data-review-id="${esc(r.id)}" ${selectedReviews.has(r.id)?'checked':''}> ${esc(r.id)} <small>${esc(r.workflow)}</small></label>`).join('')||'<p>Confirm expected results above to make reviews available here.</p>'}<p id="selection-count">${selectedReviews.size} selected</p></fieldset>`,'Create test set'));}
function settings(){return (pairMode?panel('Pair a customer SDK',`<p class="section-note">The customer's SDK generates a code locally. Pair it once using an existing Hosted task. After that, the SDK starts each new run automatically; no more task IDs to enter. Revoke access here at any time.</p>${form('worker-pair',field('workflow_id','Existing task ID (identifies customer)','','text','required')+field('code','Customer pairing code','','password','required minlength="43"'),'Pair SDK')}${snapshot.pairs.pairs.length?table(['Pairing','Customer','First task','Created',''],snapshot.pairs.pairs.map(p=>[esc(p.id),esc(p.customer_id),esc(p.workflow_id),date(p.created),button('Revoke','revoke-worker-pair',p.id)])):empty('No customer SDK paired')}`):'')+panel('Connection and Agent integration',`<div class="info-list"><div><dt>Connection</dt><dd>${pairMode?'Hosted paired workspace':'Local private workspace'}</dd></div><div><dt>Access</dt><dd>${pairMode?'Paired for seven days':'Automatic on this device'}</dd></div></div><p class="section-note">${pairMode?'Register an adapter in Experiments, then connect its worker to this hosted workspace.':'Register an adapter in Experiments, then start its worker from the same host.'}</p><pre>reins control --token-file ~/.reins/worker.token experiment-worker \\\n  --adapter my-agent-v1 --callable my_agent:run \\\n  --worker-id my-worker --state ~/.reins/agent-worker</pre><p class="section-note">Your adapter receives input, configuration and a Reins workflow. Provider keys stay on the worker.</p>`)+panel('Reconcile provider invoice',`<p class="section-note">CSV fields: provider, invoice_id, line_id, request_id, amount, revision, reference.</p><div class="actions"><input id="invoice-file" type="file" accept=".csv" aria-label="Invoice CSV">${button('Preview invoice','invoice-preview')}${button('Import reviewed rows','invoice-import','','primary').replace('<button ', '<button '+(invoiceReady?'':'disabled '))}</div><div id="invoice-result">${invoicePreview}</div><details><summary>Recent invoice revisions</summary>${table(['Invoice / line','Revision','Amount','Matched'],snapshot.pilot.bills.map(b=>[esc(b.invoice_id+' / '+b.line_id),esc(b.revision),cash(b.amount),b.matched?'Yes':'No']))}<p class="section-note">Latest 1,000 revisions. Complete ledger is retained.</p></details>`)+panel('Record business costs and revenue',form('economics',field('entry_id','Entry ID',uuid())+field('workflow_id','Workflow ID','', 'text','required')+select('kind','Entry type',['revenue','human_review','infrastructure','coverage_complete'])+field('amount','Amount (USD)',0,'number','min="0" step="0.000001"')+field('hours','Human review hours',0,'number','min="0" step="0.01"')+field('hourly_rate','Hourly rate (USD)',0,'number','min="0" step="0.01"')+field('reference','Source / reference','','text','required'),'Record entry'))+panel('Tool permission history',table(['Tool','Version','Access','Saved'],snapshot.ops.tool_history.map(t=>[esc(t.name),esc(t.digest.slice(0,12)),t.policy.read_only?'Read only':'Writes data',date(t.created)])))+panel('Notifications','<p class="muted">Budget alerts and task issues are stored in the Exceptions inbox. No external notifications are configured.</p>');}
function openDialog(title,body){dialogOrigin=document.activeElement;$('#dialog-content').innerHTML=`<h2>${esc(title)}</h2>${body}`;$('#dialog').setAttribute('aria-label',title);for(const f of $('#dialog-content').querySelectorAll('form[id]'))drafts.delete(f.getAttribute('id'));$('#dialog').showModal();restoreDrafts();}
let confirmCallback;
function confirmAction(title,description,callback){confirmCallback=callback;openDialog(title,`<p>${esc(description)}</p>`+form('confirm',field('reason','Reason','','text','required'),'Confirm'));}
function restoreDrafts(){for(const b of document.querySelectorAll("[data-width]"))b.style.width=Number(b.dataset.width)+"%";for(const f of document.querySelectorAll('form[id]')){const draft=drafts.get(f.getAttribute('id'));if(!draft)continue;for(const [k,v] of Object.entries(draft)){const input=f.elements.namedItem(k);if(input&&input.type!=='file'&&input.type!=='checkbox'&&input.type!=='hidden')input.value=v;}}}
function policyDialog(p){const w=p?.body.workflow||{},pr=p?.body.progress||{};openDialog(p?'Create a policy version':'New execution policy',form('policy',field('policy_id','New policy version',p?p.id+'-next':'','text','required')+field('budget','Task budget (USD)',w.budget||'1','number','min="0" step="0.01" required')+field('wrapup_reserve','Wrap-up reserve (USD)',w.wrapup_reserve||'0.05','number','min="0" step="0.01"')+field('repeat_limit','Same-operation limit',w.repeat_limit??5,'number','min="0"')+field('failure_limit','Consecutive failure limit',w.failure_limit??3,'number','min="0"')+field('max_iterations','Maximum paid operations',w.max_iterations??30,'number','min="1"')+field('window','Settled attempts without progress',pr.window||3,'number','min="2" max="100"')+select('action','When progress stalls',[['advise','Suggest an action'],['pause','Pause the task'],['wrapup','Stop further work']],pr.action||'advise')+field('allowed_tools','Allowed tools, comma separated',(w.allowed_tools||[]).join(', '))+area('advanced','Additional policy settings (JSON)',Object.fromEntries(Object.entries(w).filter(([k])=>!['budget','mode','wrapup_reserve','repeat_limit','failure_limit','max_iterations','allowed_tools','tool_policy_digests'].includes(k))),2)+field('preview_workflow','Existing workflow for progress preview')+`<div class="wide actions">${button('Preview progress rule','preview-policy')}</div><p id="policy-preview-result" class="form-note"></p>`,'Save immutable version'));}
function experimentVariants(v){if(v.setup==='gemini')return [{id:v.baseline,policy:v.policy,config:{model:'flash'}},{id:v.baseline==='candidate'?'lite':'candidate',policy:v.policy,config:{model:'lite'}}];let rows;try{rows=JSON.parse(v.variants);}catch{throw Error('Custom variants: enter a valid JSON list, or use the built-in Gemini preset.');}if(!Array.isArray(rows)||rows.some(x=>!x||typeof x!=='object'||Array.isArray(x)))throw Error('Custom variants must be a list of named configurations.');return rows.map(x=>({...x,policy:x.policy||v.policy}));}
function policyPayload(f){return {policy_id:f.policy_id,workflow:{...parseObject(f.advanced||'{}','Additional policy settings'),budget:f.budget,mode:'enforce',wrapup_reserve:f.wrapup_reserve,repeat_limit:Number(f.repeat_limit),failure_limit:Number(f.failure_limit),max_iterations:Number(f.max_iterations),allowed_tools:f.allowed_tools.split(',').map(v=>v.trim()).filter(Boolean)},progress:{window:Number(f.window),action:f.action}};}
async function action(act,id){const s=snapshot;if(act==='revoke-worker-pair')return confirmAction('Revoke SDK pairing','This customer SDK will immediately lose access to every task for this customer.',async f=>api('worker-pair/revoke',{id,reason:f.reason}));if(act==='open-workspace')return openWorkspace();if(act==='select-reviews'||act==='clear-reviews'){selectedReviews.clear();if(act==='select-reviews')for(const r of s.pilot.reviews.filter(r=>r.state==='approve'))selectedReviews.add(r.id);draw();return;}if(act==='nav')return navigate(id);if(act==='run')return navigate('runs',id);if(act==='experiment')return navigate('experiments',id);if(act==='sort'){sort=id;page=1;return refresh(true);}if(act==='page'){page=Number(id);return refresh(true);}if(act==='group'){group=id;return refresh(true);}if(act==='clear-filters'){filters={};page=1;return refresh(true);}if(act==='approval-tab'){approvalTab=id;return draw();}if(act==='review-tab'){approvalTab='quality';return navigate('approvals');}if(act==='new-policy')return policyDialog();if(act==='policy')return policyDialog(s.pilot.policies.find(p=>p.id===id));
if(act==='new-task')return openDialog('Create a task record',form('new-task',field('workflow_id','Task ID',uuid())+field('customer_id','Customer','','text','required')+field('task_type','Workflow type','research','text','required')+select('policy_template','Policy version',s.pilot.policies.map(p=>p.id))+field('team_id','Team','default')+select('pool_id','Shared pool',[['','No pool'],...s.pools.pools.map(p=>p.pool_id)]),'Create task record')+'<p class="small">Creates a record. Your connected Agent starts the work.</p>');
if(act==='new-budget'){const now=new Date(),end=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth()+1,1));return openDialog('New period budget',form('budget',field('id','Budget name','','text','required')+select('scope','Scope',['workspace','customer','team','task_type','model'])+field('value','Customer, team, workflow or model','*','text','disabled')+field('amount','Limit (USD)','100','number','min="0.01" step="0.01" required')+field('start','Start date and time (UTC)',new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),1)).toISOString().slice(0,16),'datetime-local','required')+field('end','End date and time (UTC)',end.toISOString().slice(0,16),'datetime-local','required')+field('thresholds','Alert thresholds (%)','80,95,100'),'Create budget'));}
if(act==='new-pool')return openDialog('New shared work pool',form('pool',field('pool_id','Pool ID',uuid())+field('customer_id','Customer','','text','required')+field('team_id','Team','','text','required')+field('budget','Budget (USD)','100','number','min="0" step="0.01"')+field('critical_reserve','Reserve for critical work','10','number','min="0" step="0.01"'),'Create pool'));
if(act==='budget-detail'){const b=s.budgets.budgets.find(b=>b.id===id);return openDialog(b.id,`<div class="metrics">${metric('Spent',cash(b.spent))}${metric('Reserved',cash(b.reserved))}${metric('Budget',cash(b.amount))}${metric('Projected at period end',cash(b.forecast))}</div>${progress(Number(b.spent)+Number(b.reserved),b.amount)}<p>Alerts at ${b.thresholds.join('%, ')}%. The hard limit applies before new paid work.</p><p class="small">Projection uses seven complete UTC days when available. Budget periods are immutable.</p>`);}
if(act==='budget-ack'){const a=s.alerts.alerts.find(x=>x.id===id);return confirmAction('Acknowledge budget alert','This records that you saw the alert.',f=>api('console/alerts/acknowledge',{id,version:a.version,reason:f.reason}));}
if(act==='issue-ack'){const a=s.ops.alerts.find(x=>x.issue_id===id);return confirmAction('Acknowledge task alert','Acknowledgement does not resume the task.',f=>api('ops/alerts/acknowledge',{issue_id:id,version:a.version,reason:f.reason}));}
if(act==='workflow-action')return confirmAction(human(id)+' task','This affects future admission. In-flight calls remain charged.',f=>api('transition',{workflow_id:detail.workflow_id,action:id,reason:f.reason}));
if(act==='issue'){const i=s.pilot.issues.find(x=>x.id===id);return openDialog('Review '+human(i.kind),`<p>Task ${esc(i.task)} · ${i.body.count} recorded occurrences</p>${jsonBox(i.body.evidence)}`+form('issue-action',`<input type="hidden" name="id" value="${esc(id)}"><input type="hidden" name="version" value="${i.version}">`+select('action','Action',[['pause','Pause task and descendants'],['resume','Resume task'],['wrapup','Stop further work'],['resolve','Mark reviewed']])+field('reason','Reason','','text','required'),'Apply decision'));}
if(act==='tool'){const t=s.ops.tools.find(t=>t.name===id);return openDialog(t?'Edit tool permissions':'Register tool',form('tool',field('name','Tool name',t?.name||'','text','required')+select('access','Access',[['read','Read only'],['write','Writes data']],t?.policy.read_only===false?'write':'read')+select('approval','Read approval',[['no','No extra approval'],['yes','Exact-call approval']],t?.policy.approval_required?'yes':'no')+area('fields','Required argument types',t?.policy.fields||{region:'string'})+area('allowed_values','Allowed argument values',t?.policy.allowed_values||{region:['US']})+`<input type="hidden" name="expected_digest" value="${esc(t?.digest||'')}">`,'Save permissions'));}
if(act==='step'){const c=detail.requests.find(c=>c.request_id===id);return openDialog(c.tool||c.model,`<p>${esc(c.task_id)} · ${cash(c.cost)} recorded</p><h3>Token usage</h3>${jsonBox(c.usage)}<h3>Recorded output</h3>${jsonBox(c.output)}<p class="small">Times show reservation-to-settlement interval, including communication overhead.</p>`);}
if(act==='copy-trace'){await navigator.clipboard.writeText(JSON.stringify(detail,null,2));return notify('Trace copied. It includes recorded task outputs.');}
if(act==='capture-run')return openDialog('Create a quality review',form('capture',field('review_id','Review ID',uuid())+field('source_version','Source version','','text','required')+area('input','Original Agent input',{})+area('output','Observed output',detail.requests.at(-1)?.output||{}),'Save pending review'));
if(act==='request-approval')return openDialog('Request an exact-call approval',form('approval-request',field('id','Request ID',uuid())+field('task_id','Task ID','','text','required')+select('tool_name','Tool',s.ops.tools.map(t=>t.name))+field('max_cost','Maximum cost (USD)','0.1','number','min="0" step="0.000001"')+field('purpose','Purpose','','text','required')+area('arguments','Exact tool arguments',{}),'Submit request'));
if(act==='approve'||act==='reject'){const a=s.approvals.approvals.find(a=>a.id===id);return confirmAction(act==='approve'?'Approve this exact call':'Reject this operation',act==='approve'?'Valid for five minutes and one execution. The Agent must still pass budget checks.':'The operation will not receive execution permission.',f=>api('console/approvals/decide',{id,version:a.version,decision:act,reason:f.reason}));}
if(act==='adapter')return openDialog('Register an Agent adapter',form('adapter',field('id','Versioned adapter ID','my-agent-v1','text','required')+field('description','Description','','text','required'),'Register adapter')+`<p class="small">For the built-in Gemini adapter use the callable <code>reins.control.worker:gemini_agent</code>. For another Agent use your installed module:function.</p>`);
if(act==='new-experiment'){if(!s.catalog.suites.length||!s.catalog.adapters.length||!s.pilot.policies.length)return notify('Create a reviewed test set, register an adapter and save a policy first.',true);return openDialog('Create an experiment',form('experiment',field('id','Experiment ID',uuid())+select('adapter','Agent adapter',s.catalog.adapters.map(a=>a.id))+select('suite_id','Reviewed test set',s.catalog.suites.map(a=>[a.id,a.id+' · '+a.cases+' cases']))+field('budget','Total experiment budget (USD)','1','number','min="0.01" step="0.01"')+select('policy','Execution policy',s.pilot.policies.map(p=>p.id))+field('baseline','Baseline variant','baseline')+select('setup','Configuration format',[['custom','Custom Agent configurations'],['gemini','Built-in Gemini: Flash vs Flash Lite']])+`<p class="form-note">Use the Gemini preset only with the built-in Gemini extraction adapter.</p>`+area('variants','Custom variant configurations',[{id:'baseline',config:{model:'flash'}},{id:'candidate',config:{model:'lite'}}])+field('min_cases','Minimum cases',30,'number','min="1"')+field('min_success_rate','Minimum acceptance (%)',95,'number','min="0" max="100" step="0.1"')+field('max_quality_drop','Allowed drop (percentage points)',0,'number','min="0" max="100" step="0.1"')+field('max_p95_ms','Maximum p95 latency (ms), optional','','number','min="1"')+area('contract','Trajectory requirements (JSON)',{},2),'Queue paid experiment')+'<p class="small">Connected workers will execute all variants. The shared experiment budget limits admission.</p>');}
if(act==='cancel-experiment')return confirmAction('Cancel remaining work','Queued work will stop. In-flight charges and returned results are retained.',f=>api('console/experiments/cancel',{id,reason:f.reason}));
if(act==='adopt')return openDialog('Adopt for new tasks',form('adopt',field('id','Deployment name','default','text','required')+`<input type="hidden" name="variant" value="${esc(id)}">`+field('reason','Decision note','','text','required'),'Adopt configuration')+'<p class="small">Running tasks keep their original configuration. New tasks using this deployment receive the chosen version.</p>');
if(act==='rollback'){const d=s.catalog.deployments.find(d=>d.id===id);return openDialog('Roll back '+id,form('rollback',`<input type="hidden" name="id" value="${esc(id)}"><input type="hidden" name="expected_version" value="${d.version}">`+field('target_version','Previous version',Math.max(1,d.version-1),'number','min="1"')+field('reason','Reason','','text','required'),'Restore for new tasks'));}
if(act==='hosted-task'){const d=s.catalog.deployments.find(d=>d.id===id);return openDialog('Start hosted task · '+id,form('hosted-start',`<input type="hidden" name="id" value="${esc(id)}">`+field('workflow_id','Task ID',uuid())+field('customer_id','Customer','','text','required'),'Create hosted task')+`<p class="small">Pins configuration version ${d.version} for a customer-owned Agent. Give its backend the task ID and worker API details, never the operator credential.</p>`);}
if(act==='deployed-task'){const d=s.catalog.deployments.find(d=>d.id===id);return openDialog('Run '+id,form('launch',`<input type="hidden" name="id" value="${esc(id)}">`+field('run_id','Task ID',uuid())+field('customer_id','Customer','','text','required')+area('input','Agent input',{}),'Queue task')+`<p class="small">Adapter ${esc(d.body.adapter)} · configuration version ${d.version}. Its connected worker will execute this task.</p>`);}
if(act==='experiment-json')return download('reins-experiment-'+report.id+'.json',JSON.stringify(report,null,2),'application/json');if(act==='print')return window.print();
if(act==='runs-csv'){const q=await allRuns();return csv('reins-runs.csv',['Task','Customer','Workflow','State','Cost USD','Reserved USD'],q.map(w=>[w.id,w.customer,w.task_type,w.state,w.cost,w.reserved]));}
if(act==='attribution-csv')return csv('reins-attribution.csv',['Name','Cost USD','Tasks','Accepted','Revenue USD','Margin USD'],s.q.groups.map(g=>[g.name,g.cost,g.tasks,g.accepted,g.revenue,g.margin]));
if(act==='preview-policy'){const f=Object.fromEntries(new FormData($('#policy')));const r=await api('pilot/policies/preview',{...policyPayload(f),workflow_id:f.preview_workflow});$('#policy-preview-result').textContent=r.historical_matches.length+' recorded tasks match this progress rule. '+r.note;return;}
if(act==='invoice-preview'){invoiceReady=false;$('[data-act=invoice-import]').disabled=true;const file=$('#invoice-file').files[0];if(!file||file.size>900000)throw Error('Choose a CSV smaller than 900 KB');invoiceRows=parseCSV(await file.text());const r=await api('pilot/invoices/preview',{rows:invoiceRows});invoiceReady=r.valid;invoicePreview=table(['Row','Match','Difference','Status'],r.rows.map(x=>[esc(x.row),x.matched?'Matched':'Unmatched',cash(x.difference),esc(x.error||(x.duplicate?'Already imported':'Ready'))]));$('#invoice-result').innerHTML=invoicePreview;$('[data-act=invoice-import]').disabled=!invoiceReady;return;}
if(act==='invoice-import'){if(!invoiceReady)throw Error('Preview a valid invoice before importing');invoiceReady=false;let n=0;try{for(const row of invoiceRows){await api('reconcile',row);n++;}invoicePreview='';invoiceRows=[];notify(n+' invoice rows imported. Revisions retained.');}catch(e){throw Error(n+' rows imported. Preview again to resume. '+e.message);}return refresh(true);}
}
async function allRuns(){const rows=[];for(let p=1;;p++){const q=await api('console/query',{...filters,start:Date.now()/1000-days*86400,page:p,page_size:100,sort});rows.push(...q.workflows);if(rows.length>=q.total)break;}return rows;}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(name,headers,rows){const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';download(name,[headers,...rows].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv');}
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('Unclosed quoted CSV field');row.push(cell);if(row.some(v=>v))rows.push(row);const headers=rows.shift()?.map(h=>h.replace(/^\uFEFF/,'').trim());if(!headers||new Set(headers).size!==headers.length)throw Error('Missing or duplicate headers');return rows.map(r=>{if(r.length!==headers.length)throw Error('CSV row width differs from header');const o=Object.fromEntries(headers.map((h,i)=>[h,r[i]]));o.revision=Number(o.revision||1);return o;});}
document.addEventListener('input',e=>{const f=e.target.closest('form');if(f?.getAttribute('id')&&f.getAttribute('id')!=='connect'&&f.method!=='dialog')drafts.set(f.getAttribute('id'),Object.fromEntries(new FormData(f)));});
document.addEventListener('change',async e=>{if(e.target.name==='scope'&&e.target.closest('#budget')){const input=$('#budget [name=value]');input.disabled=e.target.value==='workspace';input.required=!input.disabled;input.value=input.disabled?'*':'';if(!input.disabled)input.focus();}if(e.target.name==='setup'){const a=$('#experiment [name=variants]');a.disabled=e.target.value==='gemini';a.closest('label').hidden=a.disabled;}if(e.target.dataset.reviewId){e.target.checked?selectedReviews.add(e.target.dataset.reviewId):selectedReviews.delete(e.target.dataset.reviewId);$('#selection-count').textContent=selectedReviews.size+' selected';}if(e.target.dataset.filter){filters[e.target.dataset.filter]=e.target.value;page=1;await refresh(true);}if(e.target.id==='date-range'){days=Number(e.target.value);page=1;await refresh(true);}if(e.target.id==='run-state'){filters.state=e.target.value;page=1;await refresh(true);}if(e.target.id==='run-search'){filters.search=e.target.value;page=1;await refresh(true);}if(e.target.id==='invoice-file'){invoiceRows=[];invoiceReady=false;invoicePreview='';$('#invoice-result').innerHTML='';$('[data-act=invoice-import]').disabled=true;}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-act]');if(!b)return;const disabled=b.disabled;b.disabled=true;try{$('#notice').hidden=true;await action(b.dataset.act,b.dataset.id);}catch(err){notify(err.message,true);}finally{b.disabled=disabled;}});
document.addEventListener('submit',async e=>{const f=e.target;if(f.method==='dialog')return;if(f.getAttribute('id')==='connect')return;e.preventDefault();if(f.dataset.submitting)return;f.dataset.submitting='true';f.querySelector('.inline-error')?.remove();$('#notice').hidden=true;const v=Object.fromEntries(new FormData(f));const submit=f.querySelector('button[type=submit],button:not([type])');if(submit)submit.disabled=true;try{let result;
if(f.getAttribute('id')==='confirm')result=await confirmCallback(v);
else if(f.getAttribute('id')==='budget')result=await api('console/budgets/save',{...v,value:v.scope==='workspace'?'*':v.value,start:v.start+'Z',end:v.end+'Z',thresholds:v.thresholds.split(',').map(Number)});
else if(f.getAttribute('id')==='pool')result=await api('pools',v);
else if(f.getAttribute('id')==='new-task'){if(!v.pool_id)delete v.pool_id;result=await api('workflows',v);}
else if(f.getAttribute('id')==='policy')result=await api('pilot/policies/save',policyPayload(v));
else if(f.getAttribute('id')==='tool')result=await api('ops/tools/save',{name:v.name,read_only:v.access==='read',approval_required:v.approval==='yes',fields:parseObject(v.fields,'Argument types'),allowed_values:parseObject(v.allowed_values,'Allowed values'),expected_digest:v.expected_digest||null});
else if(f.getAttribute('id')==='issue-action')result=await api('pilot/issues/action',{issue_id:v.id,version:Number(v.version),action_id:uuid(),action:v.action,reason:v.reason});
else if(f.getAttribute('id')==='capture')result=await api('pilot/reviews/submit',{...v,workflow_id:detail.workflow_id,input:parseObject(v.input,'Agent input'),output:parseObject(v.output,'Observed output')});
else if(f.getAttribute('id')==='approval-request')result=await api('console/approvals/request',{...v,arguments:parseObject(v.arguments,'Tool arguments')});
else if(f.getAttribute('id').startsWith('review-')){const id=f.getAttribute('id').slice(7),r=snapshot.pilot.reviews.find(r=>r.id===id);result=await api('pilot/reviews/decide',{...v,review_id:id,version:r.version,expected:v.decision==='approve'?parseObject(v.expected,'Expected fields'):{}});}
else if(f.getAttribute('id')==='suite'){if(!selectedReviews.size)throw Error('Select at least one approved review.');result=await api('pilot/suites/export',{suite_id:v.suite_id,review_ids:[...selectedReviews]});selectedReviews.clear();}
else if(f.getAttribute('id')==='adapter')result=await api('console/adapters/save',v);
else if(f.getAttribute('id')==='experiment'){result=await api('console/experiments/create',{id:v.id,adapter:v.adapter,suite_id:v.suite_id,budget:v.budget,baseline:v.baseline,variants:experimentVariants(v),constraints:{min_cases:Number(v.min_cases),min_success_rate:Number(v.min_success_rate)/100,max_quality_drop:Number(v.max_quality_drop)/100,max_p95_ms:v.max_p95_ms?Number(v.max_p95_ms):null},contract:parseObject(v.contract,'Trajectory requirements')});}
else if(f.getAttribute('id')==='hosted-start')result=await api('console/deployments/start',v);
else if(f.getAttribute('id')==='launch')result=await api('console/deployments/launch',{...v,input:parseObject(v.input,'Agent input')});
else if(f.getAttribute('id')==='adopt'){const d=snapshot.catalog.deployments.find(d=>d.id===v.id);result=await api('console/deployments/adopt',{...v,experiment:report.id,expected_version:d?.version||0});}
else if(f.getAttribute('id')==='rollback')result=await api('console/deployments/rollback',{...v,expected_version:Number(v.expected_version),target_version:Number(v.target_version)});
else if(f.getAttribute('id')==='economics')result=await api('economics',v);
else if(f.getAttribute('id')==='worker-pair')result=await api('worker-pair/register',v);
else return;
drafts.delete(f.getAttribute('id'));if($('#dialog').open)$('#dialog').close();notify(f.getAttribute('id')==='experiment'?'Experiment queued for its registered worker.':f.getAttribute('id')==='hosted-start'?'Hosted task pinned. Connect its Agent using the worker API.':'Saved successfully.');if(f.getAttribute('id')==='hosted-start')navigate('runs',result.context.workflow_id);else await refresh(true);
}catch(err){notify(err.message,true);let note=f.querySelector('.inline-error');if(!note){note=document.createElement('p');note.className='inline-error form-note';note.setAttribute('role','alert');f.append(note);}note.textContent=err.message;}finally{delete f.dataset.submitting;if(submit)submit.disabled=false;}});
function showPair(message=''){$('#pair-screen').hidden=false;document.body.classList.add('pairing');$('#pair-error').textContent=message;$('#pair-error').hidden=!message;$('#pair-token').focus();}
function enterWorkspace(){document.body.classList.remove('pairing');$('#pair-screen').hidden=true;readRoute();clearInterval(timer);timer=setInterval(()=>refresh(),5000);}
async function openWorkspace(){
try{
 const mode=await fetch(apiBase+'pair/mode',{signal:AbortSignal.timeout(15000)});
 if(!mode.ok)throw Error('Workspace connection is unavailable.');
 pairMode=(await mode.json()).pairing;
 if(pairMode){
  credential=localStorage.getItem(pairStorageKey)||'';
  if(credential){try{await api('console/pools');enterWorkspace();return;}catch{credential='';localStorage.removeItem(pairStorageKey);}}
  showPair();return;
 }
 const response=await fetch(apiBase+'local-session',{headers:{'X-Reins-Local-UI':'1'},signal:AbortSignal.timeout(15000)});
 if(!response.ok)throw Error('Workspace access is unavailable. Check that the local Reins service is running.');
 credential=(await response.json()).token;
 enterWorkspace();
}catch(e){notify(e.message,true);$('#content').innerHTML=empty('Unable to open workspace','Check the service and try again.')+button('Try again','open-workspace');}
}
$('#pair-form').addEventListener('submit',async e=>{e.preventDefault();const input=$('#pair-token'),submit=$('#pair-form button');submit.disabled=true;$('#pair-error').hidden=true;try{const response=await fetch(apiBase+'pair/claim',{method:'POST',headers:{'Content-Type':'application/json','X-Reins-Pair':'1'},body:JSON.stringify({token:input.value.trim()}),signal:AbortSignal.timeout(15000)});const result=await response.json();if(!response.ok)throw Error(result.error||'Pairing failed');credential=result.token;localStorage.setItem(pairStorageKey,credential);input.value='';enterWorkspace();}catch(error){showPair(error.message);}finally{submit.disabled=false;}});
$('#menu').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open));};document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');}});$('#dialog').addEventListener('close',()=>{if(dialogOrigin?.isConnected)dialogOrigin.focus();});window.addEventListener('hashchange',readRoute);readRoute();

openWorkspace();
